bool CixiaoCard::targetFilter(const QList<const Player*>&targets,const Player*to_select,const Player*)const
{
	if(targets.length()> 1)return false;
	if(targets.isEmpty())
		return to_select->getMark("&cxyizi")> 0;
	return true;
}

