{
	will_throw = false;
	handling_method = Card::MethodNone;
}

bool ThShuliangCard::targetFilter(const QList<const Player*>&targets,const Player*to,const Player*Self)const
{
	return targets.length()<subcardsLength()&&to!=Self&&to->isKongcheng();
}

