	{
	}

	bool isEnabledAtPlay(const Player*player)const
	{
		if(!player->canPindian())return false;
		return player->usedTimes("FenyueCard")< player->getMark("fenyue-PlayClear");
	}

	const Card*viewAs()const
	{
		return new FenyueCard;
	}
